import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.kOe0DhAP.js";const b=JSON.parse('{"title":"业务概述","description":"现货交易以基础币与计价币的交换为核心。","frontmatter":{"title":"业务概述","description":"现货交易以基础币与计价币的交换为核心。"},"headers":[],"relativePath":"06/0601/060001.md","filePath":"06/0601/060001.md"}'),i={name:"06/0601/060001.md"};function l(o,t,h,s,n,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="业务概述" tabindex="-1">业务概述 <a class="header-anchor" href="#业务概述" aria-label="Permalink to &quot;业务概述&quot;">​</a></h1><div class="doc-lead">现货交易以基础币与计价币的交换为核心。</div><p>本手册面向希望理解现货订单、资金占用与成交结算如何串起来的产品与研发读者。它解释业务规则与设计职责，不逐行讲解源码。若还不熟悉委托、冻结与结算等基础概念，可先阅读<a href="/03/0303/030003">交易所基础知识</a>。</p><h2 id="basics" tabindex="-1">现货交易基础 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;现货交易基础 {#basics}&quot;">​</a></h2><p>在 BTC/USDT 交易对中，买方支付 USDT 获得 BTC，卖方支付 BTC 获得 USDT。系统需要确保订单符合规则、被占用的资金不能重复使用、成交后双方资产正确变化。</p><p>现货不是“订单价格变动后直接计算收益”的游戏，资产交换是它与周期结果类产品的重要区别。合约关注持仓与保证金，期权关注周期与结果判定；现货则始终围绕「订单 → 成交 → 资产交换」闭环展开。</p><p>理解现货时，建议把三个对象分开看：</p><table tabindex="0"><thead><tr><th>对象</th><th>回答什么问题</th></tr></thead><tbody><tr><td>委托</td><td>还想买/卖多少，处于什么状态</td></tr><tr><td>成交</td><td>实际换了多少、按什么价格</td></tr><tr><td>账务</td><td>可用、冻结与资产归属如何变化</td></tr></tbody></table><h2 id="interface" tabindex="-1">交易界面与核心术语 <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;交易界面与核心术语 {#interface}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>界面区域</th><th>业务含义</th></tr></thead><tbody><tr><td>交易对</td><td>说明交换的两种资产</td></tr><tr><td>盘口</td><td>展示当前买卖挂单的价格和数量</td></tr><tr><td>下单区域</td><td>表达方向、类型、价格或数量</td></tr><tr><td>当前委托</td><td>仍有未完成部分的订单</td></tr><tr><td>成交记录</td><td>实际成交的价格、数量和时间</td></tr><tr><td>K 线</td><td>某一时间区间内行情的聚合</td></tr></tbody></table><p>盘口反映尚未成交的挂单意图，成交记录反映已经发生的交换事实，两者不能混用。页面上的余额是结果展示，判断一笔交易是否正确，仍要以委托、成交和账务记录为准。</p><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><ol><li><a href="/06/0602/060002">系统架构</a> — 认识委托、撮合、账户与行情的职责边界。</li><li><a href="/06/0603/060003">交易规则</a> — 弄清什么订单合法、精度与手续费要说明哪些点。</li><li><a href="/06/0604/060004">核心设计</a> — 理解冻结、状态与订单簿。</li><li><a href="/06/0605/060005#complete">核心交易流程</a> — 用贯穿示例把资金变化串起来。</li><li><a href="/06/0606/060006">行情与推送</a> / <a href="/06/0607/060007">异常处理</a> — 补齐展示层与失败路径。</li></ol><p>贯穿示例统一为：买入 0.01 BTC，先成交 0.006 BTC，再撤销剩余 0.004 BTC。后续章节尽量沿用同一组假设，避免每页换一套数字。</p>',15)])])}const f=a(i,[["render",l]]);export{b as __pageData,f as default};
